(()=>{"use strict";const money=n=>typeof window<"u"&&window.CMI18n?window.CMI18n.currency(Number(n),"USD",{maximumFractionDigits:2,minimumFractionDigits:2}):"$"+Number(n).toLocaleString("en-US",{maximumFractionDigits:2,minimumFractionDigits:2}),num=n=>Number(n).toLocaleString(typeof window<"u"&&window.CMI18n?window.CMI18n.formatLocale:"en-US",{maximumFractionDigits:2}),$=id=>document.getElementById(id);function get(){const v={};return document.querySelectorAll("input").forEach(e=>{v[e.id]=parseFloat(e.value)||0}),v}function calc(v){const hours=v.people*v.runs*v.mins/60,gross=hours*v.hourly,net=gross-v.fee;return{hours,gross,net,perPerson:v.people>0?net/v.people:0}}function render(){const v=get();if(!(v.people>0&&v.runs>=0&&v.mins>=0&&v.hourly>=0&&v.fee>=0)){$("result").textContent="\u2014",$("chipA").textContent="\u2014",$("chipB").textContent="\u2014",$("chipC").textContent="\u2014",$("breakRows").innerHTML="",$("bars").innerHTML="",$("cumRows").innerHTML="";const vd2=$("verdict");vd2.className="verdict warn",$("verdictText").textContent="Enter a team size above zero, with runs, minutes, hourly cost, and fee at zero or above, to see the estimate.",window.__summary="";return}const r=calc(v);$("result").textContent=money(r.net),$("chipA").textContent=num(r.hours)+" hrs",$("chipB").textContent=money(r.gross),$("chipC").textContent=money(r.perPerson);const row=(l,val)=>"<tr><td>"+l+"</td><td class='num'>"+val+"</td></tr>";$("breakRows").innerHTML=row("Total runs per month",num(v.people*v.runs))+row("Hours saved per month",num(r.hours)+" hrs")+row("Gross time value",money(r.gross))+row("Monthly tool fee",money(v.fee))+row("Monthly net value",money(r.net))+row("Net value per person",money(r.perPerson)),$("bars").innerHTML=barRow("Gross time value",money(r.gross),Math.max(r.gross,0),Math.max(r.gross,v.fee,1),"")+barRow("Tool fee",money(v.fee),v.fee,Math.max(r.gross,v.fee,1),"newbad"),$("cumRows").innerHTML=row("After 1 month",money(r.net*1))+row("After 3 months",money(r.net*3))+row("After 6 months",money(r.net*6))+row("After 12 months",money(r.net*12));const vd=$("verdict");r.net<0?(vd.className="verdict bad",$("verdictText").textContent="Negative on these inputs: the "+money(v.fee)+" monthly fee exceeds the "+money(r.gross)+" gross time value, a shortfall of "+money(-r.net)+" per month. Either the minutes saved, the run count, or the hourly value is too low to cover the fee \u2014 check the minutes-saved figure against timed runs before renewing."):r.net===0?(vd.className="verdict warn",$("verdictText").textContent="Exactly break-even: gross time value equals the fee. Any drop in usage or minutes saved turns this negative."):(vd.className="verdict",$("verdictText").textContent="Positive on these inputs: "+num(r.hours)+" hours saved are worth "+money(r.gross)+" against a "+money(v.fee)+" fee, leaving "+money(r.net)+" per month ("+money(r.perPerson)+" per person). Remember this values time at full hourly cost \u2014 it is cash saved only if the freed time is actually redeployed."),window.__summary="AI workflow savings: "+money(r.net)+"/month net ("+num(r.hours)+" hrs x $"+num(v.hourly)+" = "+money(r.gross)+" minus $"+num(v.fee)+" fee)."}function barRow(l,disp,val,maxV,cls){const p=maxV>0?Math.max(0,Math.min(100,val/maxV*100)):0;return"<div class='bar-row'><label><span>"+l+"</span><span>"+disp+"</span></label><div class='bar'><i class='"+cls+"' style='width:"+p+"%'></i></div></div>"}document.querySelectorAll("input").forEach(e=>e.addEventListener("input",render)),render()})();
